import{d as c,C as t,o as g,c as u,j as a,a as n,E as s,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第二十五章","description":"从混成先天地到四大与道法自然，理解道的命名及其限度。","frontmatter":{"title":"道德经第二十五章","description":"从混成先天地到四大与道法自然，理解道的命名及其限度。","category":"guide","aliases":["道德经第二十五章","老子第二十五章","dao de jing chapter 25"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-25.md","filePath":"daoism/dao-de-jing/chapter-25.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-25.md"},y=c({...b,setup(p){const i=[{id:"undifferentiated-and-independent",label:"有物混成，先天地生",showLabel:!0,sentences:[["有物",{text:"混成",glossary:"huncheng"},"，先天地生。"],[{text:"寂兮寥兮",glossary:"jiliao"},"，独立而不改，"]],note:["【白话】有一种浑然一体、难以分别的存在，先于天地而生。它无声无形，不依其他事物而立，也不失其常。","【王弼注择要】「混然不可得而知，而万物由之以成。」寂寥，注说「寂寞无形体也」；不改则以「返化终始，不失其常」申说。","【读法】先天地生是在古典语言中追问天地所由，不据此给出宇宙年代或物理实体。独立不改与下文周行并说，不表示僵止不动。"]},{id:"circulating-and-nurturing",label:"周行而不殆，可以为天下母",showLabel:!0,sentences:[[{text:"周行",glossary:"zhouxing"},"而不",{text:"殆",glossary:"dai"},"，可以为天下母。"]],note:["【白话】周遍运行而不陷危殆，可以作为天下万物生养的根源。母承接由之以成，强调生养所由。","【王弼注择要】「周行无所不至而免殆。」注继而说明能生成、保全有形之物，才可以称为天下母。","【读法】周行不是已知天体的轨道，也不意味着每件具体事情都会原样循环。母是生养根源的譬喻，与第六、第二十章可相参。"]},{id:"provisional-names",label:"吾不知其名，字之曰道",showLabel:!0,sentences:[["吾不知其",{text:"名",glossary:"ming"},"，",{text:"字",glossary:"zi"},"之曰道，",{text:"强",glossary:"qiang"},"为之名曰大。"]],note:["【白话】我不知道它确切的名字，姑且给它一个称号叫道；勉强为它命名，叫作大。这是在难以定形、定名时作出的称述。","【王弼注择要】「名以定形，字以称可言。」王弼区分定形之名与可言之称；又说「有分则失其极矣」，指出一旦限定，便难尽其极。","【读法】字在此作动词，取给予称号；强读 qiǎng。道与大都帮助说出一面，不应把称述的名称当作已经穷尽对象本身。"]},{id:"departing-reaching-returning",label:"大曰逝，逝曰远，远曰反",showLabel:!0,sentences:[["大曰",{text:"逝",glossary:"shi"},"，逝曰远，远曰",{text:"反",glossary:"fan"},"。"]],note:["【白话】大又意味着运行而往，往而至远，远又返归。它不局守一个范围，也不因走向某处便失去自身所本。","【王弼注择要】「逝，行也。」注又说「不偏于一逝」及「不随于所适，其体独立」，以周遍而不局于一向解释远与反。","【读法】反取返归义。三个曰层层申说大，不宜只读成空间越走越远后必在某刻机械掉头；王注同时保留周行与独立两面。"]},{id:"four-greats",label:"域中有四大，而王居其一焉",showLabel:!0,sentences:[["故道大，天大，地大，",{text:"王",glossary:"wang"},"亦大。"],[{text:"域",glossary:"yu"},"中有四大，而王居其一焉。"]],note:["【白话】所以道大，天大，地大，王也大。在所说的域中有四大，而王居其中之一。这里把人主置入道、天、地的关系之中。","【王弼注择要】「四大，道天地王也。」注又说「处人主之大也」，明指王为人主；其域的说明还连到无称，不能只当作一幅有边界的地理图。","【读法】王字保留；本页不暗换成人人皆大的现代说法。王居其一带有古代政治秩序背景，其地位仍在下文法地、法天、法道的关系中受约束。"]},{id:"following-what-is-so",label:"人法地，地法天，天法道，道法自然",showLabel:!0,sentences:[["人",{text:"法",glossary:"fa"},"地，地法天，天法道，道法",{text:"自然",glossary:"ziran"},"。"]],note:["【白话】人取法于地，地取法于天，天取法于道，道依循本然如此。这里从人的行事逐层说到所由的根据，最终不再另立一个外在主宰。","【王弼注择要】「法，谓法则也。」注以「在方而法方，在圆而法圆，于自然无所违也」申说，又说「自然者，无称之言，穷极之辞也」。自然不是另一个有名有形之物。","【读法】自然在此不是现代自然环境这一分类；法也不能只理解为机械模仿。循王弼取径，重点在不违事物本然，而非以自己的定式强制万物。"]}],r=[{id:"huncheng",term:"混成",sense:1},{id:"jiliao",term:"寂寥",sense:1},{id:"zhouxing",term:"周行",sense:1},{id:"dai",term:"殆",sense:1},{id:"ming",term:"名",sense:2},{id:"zi",term:"字",sense:1},{id:"qiang",term:"强",sense:1,pinyin:"qiǎng"},{id:"shi",term:"逝",sense:1},{id:"fan",term:"反",sense:1},{id:"wang",term:"王",sense:2},{id:"yu",term:"域",sense:1},{id:"fa",term:"法",sense:1},{id:"ziran",term:"自然",sense:1}];return(x,e)=>{const o=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),u("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第二十五章",tabindex:"-1"},[n("道德经第二十五章 "),a("a",{class:"header-anchor",href:"#道德经第二十五章","aria-label":'Permalink to "道德经第二十五章"'},"​")],-1)),s(o,{title:"怎样称述先天地的混成，又怎样理解自然",summary:"本章先以混成、寂寥与周行说天地所由，再说明道与大都是勉强的称述；逝远反、域中四大，最后接到人法地与道法自然。",points:[{label:"先读",text:"先把无定形而能周遍生养的叙述连起来，不急于画出道的样子。"},{label:"再辨",text:"名、字、大的说法都带着表达限度；大不是单指体积。"},{label:"后看",text:"保留王居四大之一的原句，再辨自然为何不是道外另一个主宰。"}],hint:"王字沿用本站正文及所据王注；不改作人。自然取本然如此义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),s(l,{sections:i,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),s(d,{lines:[{text:"有物混成，先天地生。",tone:"天地所由",guide:"保留古典追问的尺度，不将混成直接指认为某个现代物理对象。"},{text:"吾不知其名，字之曰道，强为之名曰大。",tone:"名称的限度",guide:"不知、字之、强为之，反复提示可说之称与所指之间仍有距离。"},{text:"人法地，地法天，天法道，道法自然。",tone:"取法与本然",guide:"循注从不违本然理解法，不再为自然安排一个外在于道的实体位置。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),s(h,{items:r}),e[4]||(e[4]=m('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-独立不改与周行不殆是否相冲突" tabindex="-1">象：独立不改与周行不殆是否相冲突？ <a class="header-anchor" href="#象-独立不改与周行不殆是否相冲突" aria-label="Permalink to &quot;象：独立不改与周行不殆是否相冲突？&quot;">​</a></h3><p>前者说不依外物而失其常，后者说运行无所不至。王弼以返化终始、不失其常将二者相连；若把不改读成一动不动，才会把句子拆成矛盾。</p><h3 id="理-为什么已经称为道-还要强名曰大" tabindex="-1">理：为什么已经称为道，还要强名曰大？ <a class="header-anchor" href="#理-为什么已经称为道-还要强名曰大" aria-label="Permalink to &quot;理：为什么已经称为道，还要强名曰大？&quot;">​</a></h3><p>道从无物不由这一面作称述，大再尝试说其周遍无所不至。王弼同时提醒名会限定、分别，故这些说法都有表达上的限度；不能把大缩成尺寸，也不能以无名拒绝一切讨论。</p><h3 id="用-道法自然能不能直接等于想怎样就怎样" tabindex="-1">用：道法自然能不能直接等于想怎样就怎样？ <a class="header-anchor" href="#用-道法自然能不能直接等于想怎样就怎样" aria-label="Permalink to &quot;用：道法自然能不能直接等于想怎样就怎样？&quot;">​</a></h3><p>不能。循王弼不违本然的解释，先需辨认具体条件、他者需要与事情自身的限度。现实中的制度、责任与选择仍要论证，不能只用自然二字替个人偏好背书。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>让名称保持可修订。</strong> 给项目、关系或经验命名能帮助交流，但也可能遮掉未被涵盖的部分。使用一个概念时，可以同时交代它说明了什么、尚未说明什么。</p><p><strong>取法先从辨认条件开始。</strong> 行动之前观察环境、资源、节奏与相互依赖，再决定如何参与。由本然得到的是认识条件的提醒，不是把现存一切都判成合理。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我正在依循的规则，是从事情的实际条件中看出来的，还是把自己的偏好当作了自然？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>本站保留「独立而不改」，所据 HFL 录文作「独立不改」；其他句序及「王亦大」「王居其一焉」沿本站正文，不改王为人。</li><li>字作给予称号，强读 qiǎng；反作返归。自然仍引用字典本然如此义，不另造自然神或等同现代环境概念。</li><li>本页古注择要据 HFL 电子录文核对，不等同于影印逐字校勘；现代启发是本站引申，不冒充王弼原意。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_002.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷二 HFL 本电子录文，003b–005a</a>。</p>',15))])}}});export{_ as __pageData,y as default};
